// Sample tokenizations generated by scripts/tokenizer-samples.py from the released tokenizer
// files, plus helpers to draw whitespace visibly. Nothing here is typed by hand.
import data from '../../data/tokenizer-samples.json';

export interface Chip {
  text: string;
  ids: number[];
  /** Present when one character is split across several tokens: each token's bytes, hex. */
  bytes?: string[];
}
export interface SampleRow {
  pieces: string[];
  bytePieces: string[];
  count: number;
  chips: Chip[];
}
export interface TokenizerSamples {
  repo: string;
  samples: Record<string, SampleRow>;
  chat: { source: string; parts: [boolean, string][]; tokens: number } | null;
}

export const SAMPLES: { id: string; label: string; text: string }[] = data.samples;
export const GENERATOR: string = data.generator;
export const RELATIONS: { from: string; to: string; baseTokens: number; tokensKept: number; sameId: number; merges: number; mergesKept: number }[] = data.relations;

export function samplesFor(id: string, where: string): TokenizerSamples {
  const t = (data.tokenizers as Record<string, TokenizerSamples>)[id];
  if (!t) throw new Error(`${where}: no generated samples for tokenizer "${id}"; run python3 scripts/tokenizer-samples.py`);
  return t;
}

/** Split text into runs, marking spaces, line breaks and tabs so they can be drawn (· ↵ →). */
export function visible(text: string): { t: string; ws: boolean }[] {
  const out: { t: string; ws: boolean }[] = [];
  for (const ch of text) {
    const glyph = ch === ' ' ? '·' : ch === '\n' ? '↵' : ch === '\t' ? '→' : null;
    const last = out.at(-1);
    if (glyph) {
      if (last?.ws) last.t += glyph;
      else out.push({ t: glyph, ws: true });
    } else if (last && !last.ws) last.t += ch;
    else out.push({ t: ch, ws: false });
  }
  return out;
}
